    for x in range(1, n + 1):
        # Track occupied days using a bytearray
        occupied = bytearray(n + 2)
        total_occupied = 0

        for l, r in offers:
            length = r - l + 1
            if length >= x:
                # Check if the entire range is free
                can_accept = True
                for day in range(l, r + 1):
                    if occupied[day]:
                        can_accept = False
                        break

                if can_accept:
                    # Mark all days as occupied
                    for day in range(l, r + 1):
                        occupied[day] = 1
                    total_occupied += length

        results.append(total_occupied)

    return '\n'.join(map(str, results)) + '\n'

