    # Try to find k valid cycles first
    found_cycles = []
    used_representative = set()
    visited = [False] * (n + 1)

    def dfs_find_cycle(start, current, path, visited_set):
        found = [False]
        for neighbor in adj[current]:
            if neighbor == start and len(path) > 0:
                # Found a cycle
                cycle = path + [start]
                # Check length
                cycle_len = len(cycle)
                if cycle_len >= 3 and cycle_len % 3 != 0:
                    # Check if start is representative
                    if start not in used_representative:
                        found_cycles.append(cycle)
                        used_representative.add(start)
                        found[0] = True
                elif neighbor in path:
                    # Back edge to an ancestor, found cycle
                    idx_in_path = -1
                    for i, node in enumerate(path):
                        if node == neighbor:
                            idx_in_path = i
                            break
                    if idx_in_path != -1:
                        cycle = path[idx_in_path:] + [neighbor]
                        cycle_len = len(cycle)
                        if cycle_len >= 3 and cycle_len % 3 != 0:
                            if neighbor not in used_representative:
                                found_cycles.append(cycle)
                                used_representative.add(neighbor)
                                found[0] = True
                break
        return found

    # Iterative DFS for finding cycles
    representative_candidates = list(range(1, n + 1))

    for rep in representative_candidates:
        if len(found_cycles) >= k:
            break

        visited_dfs = set()
        stack = [(rep, rep, [rep])]

        while stack and len(found_cycles) < k:
            node, start, path = stack.pop()

            if node in visited_dfs:
                continue
            visited_dfs.add(node)

            for neighbor in adj[node]:
                if neighbor == start:
                    if len(path) >= 3:
                        cycle_len = len(path)
                        if cycle_len % 3 != 0:
                            found_cycles.append(path + [start])
                            used_representative.add(start)
                            break
                elif neighbor not in path:
                    stack.append((start, start, path + [neighbor]))
                    # Check for back edges in next iteration

    # Check if we found k valid cycles
    if len(found_cycles) >= k:
        # Remove duplicates and sort by representative
        result_cycles = []
        for cyc in found_cycles:
            rep = cyc[0]
            if rep not in used_representative:
                used_representative.add(rep)
                result_cycles.append(cyc)

        if len(result_cycles) >= k:
            result_cycles = result_cycles[:k]
            output_lines = ["CYCLES"]
            for cyc in result_cycles:
                output_lines.append(str(len(cyc)))
                output_lines.append(' '.join(map(str, cyc)))
            return '\n'.join(output_lines)

    # If cycles don't work, try to find a long path
    output_lines = ["PATH"]

    # Find longest path using BFS/DFS
    # Since each vertex has degree >= 3, path should be fairly long
    start_node = 1
    stack = [start_node]
    visited_path = {start_node}
    current_path = [start_node]
    max_path = [start_node]

    while stack:
        node = stack.pop()
        for neighbor in adj[node]:
            if neighbor not in visited_path:
                visited_path.add(neighbor)
                new_path = current_path + [neighbor]
                if len(new_path) > len(max_path):
                    max_path = new_path
                stack.append((node, neighbor))

    if len(max_path) >= n / k:
        output_lines.append(str(len(max_path)))
        output_lines.append(' '.join(map(str, max_path)))
        return '\n'.join(output_lines)

    return "PATH" + '\n1' + '\n' + ' '.join(map(str, max_path))

