def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    memo = {}

    def get_grundy(val):
        if val == 0:
            return 0
        if val in memo:
            return memo[val]

        reachable = set()

        # Option 1: Remove 1 cow
        reachable.add(get_grundy(val - 1))

        # Option 2: Split if even (pile size = 2x)
        if val % 2 == 0:
            x = val // 2
            gx = get_grundy(x)
            if k % 2 == 1:
                # k is odd: XOR of k copies of gx equals gx
                reachable.add(gx)
            else:
                # k is even: XOR of k copies of gx equals 0
                reachable.add(0)

        # MEX (Minimum Excluded value)
        result = 0
        while result in reachable:
            result += 1

        memo[val] = result
        return result

    xor_sum = 0
    for x in a:
        xor_sum ^= get_grundy(x)

    return "Kevin\n" if xor_sum != 0 else "Nancy\n"

