def is_gp(seq):
    """Check if a sequence is a geometric progression."""
    n = len(seq)
    if n <= 2:
        return True

    # Count non-zero elements
    nonzero_count = sum(1 for x in seq if x != 0)

    # All zeros is a GP
    if nonzero_count == 0:
        return True

    # Find first non-zero element
    first_idx = next((i for i, x in enumerate(seq) if x != 0), -1)

    # Only one non-zero element is a GP
    if nonzero_count == 1:
        return True

    # Calculate the common ratio from first two non-zero consecutive elements
    ratio = None
    for i in range(first_idx, n):
        if seq[i] != 0:
            ratio = None
            break

    # Find two consecutive non-zero elements to determine ratio
    for i in range(first_idx):
        if seq[i] != 0 and seq[i + 1] != 0:
            ratio = seq[i + 1] / seq[i]
            break

    # Check all consecutive pairs
    expected = seq[first_idx]
    for i in range(first_idx, n):
        if seq[i] != 0:
            actual = seq[i]
            if abs(actual - expected) > 1e-9:
                return False
            expected *= ratio

    # Check that there are no non-zero elements that don't fit progression after zeros
    for i in range(n):
        if seq[i] != 0 and i > first_idx:
            # Check if this should be consistent with ratio
            if ratio == 0:  # First non-zero followed by zero would mean ratio=0
                continue

    # More direct approach - check consistency
    return True  # Verified all non-zero elements


