        char_to_vowel_type[c] = v_c_str[i]  # 'V' or 'C'

    # Parse n, m
    n, m = map(int, lines[1].split())

    # Parse rules - each rule is if pos1 has type t1, then pos2 has type t2
    rules = []
    rule_idx = 2
    i = 0
    while rule_idx < len(lines):
        parts = lines[rule_idx].split()
        pos1 = int(parts[0])
        t1 = parts[1]
        pos2 = int(parts[2])
        t2 = parts[3]
        rules.append((pos1, t1, pos2, t2))
        rule_idx += 1

    # Parse string s
    s = lines[rule_idx]

    def get_vowel_type_at(pos, char):
        """Get if a character at position pos is V or C"""
        if pos < 0 or pos >= n:
            return None
        return char_to_vowel_type[char]

    def check_rule(result, pos1, t1, pos2, t2):
        """Check if rule (pos1, t1, pos2, t2) is satisfied by result"""
        pos1_idx = pos1 - 1
        pos2_idx = pos2 - 1

        ch1 = result[pos1_idx]
        ch2 = result[pos2_idx]

        type1 = char_to_vowel_type[ch1]
        type2 = char_to_vowel_type[ch2]

        if type1 == t1:
            return type2 == t2
        return True  # Rule doesn't apply if type1 != t1

    def is_valid(result):
        """Check if a complete word satisfies all rules"""
        for pos1, t1, pos2, t2 in rules:
            if not check_rule(result, pos1, t1, pos2, t2):
                return False
        return True

    def can_complete_fixed(result, pos):
        """
        Check if it's possible to complete a word from position pos
        (with result[0...pos-1] already fixed)

        Returns True if there exists at least one valid completion
        """
        n_remaining = n - pos

        if n_remaining == 0:
            # Word is complete
            return is_valid(result)

        # Try to fill remaining positions
        # We'll use a helper to try all completions
        return can_fill_remaining(result, pos)

    def can_fill_remaining(result, pos):
        """
        Try to fill positions from pos onwards
        Returns True if we can complete the word
        """
        # Try all possible characters for current position
        for char in alphabet:
            result[pos] = char

            # Quick check: see if any rule is violated that we can't fix
            if rules_constrain(pos + 1, result, char):
                # If current character causes violation through its constraints
                # that we cannot fix, try next
                continue

            if pos + 1 < n and pos < n - 1:
                if can_fill_remaining(list(result), pos + 1):
                    return True
            else:
                if is_valid(list(result)):
                    return True

        return False

    def rules_constrain(pos, result, char_at_pos):
        """
        Check if any rules are violated by current prefix that cannot be fixed later
        """
        # Pre-check rules for current position
        for pos1, t1, pos2, t2 in rules:
            p1 = pos1 - 1
            p2 = pos2 - 1

            # Rule involves position 'pos' as pos1
            if p1 == pos:
                # Check if condition is met and result violated
                type_at_pos1 = char_to_vowel_type[result[pos]]
                if type_at_pos1 == t1:
                    # Then pos2 must have type t2
                    if p2 >= pos:
                        # pos2 is already filled - check if it's violated
                        type_at_pos2 = char_to_vowel_type[result[p2]]
                        if type_at_pos2 != t2:
                            return True
                    # If pos2 is in future, we can potentially fix it
                    continue

            # Rule involves position 'pos' as pos2
            elif p2 == pos:
                # Check if pos1 condition is met
                if p1 >= pos:
                    # pos1 is in future, condition may not be met
                    continue
                else:
                    type_at_pos1 = char_to_vowel_type[result[p1]]
                    if type_at_pos1 == t1:
                        # Then pos (pos2) must be t2
                        type_at_pos2 = char_to_vowel_type[char_at_pos]
                        if type_at_pos2 != t2:
                            return True
        return False

    def can_complete_prefix(result, pos):
        """
        Check if a partial word can be completed to satisfy all rules
        """
        # Try to complete using DFS
