def final_solution(input_data):
    lines = input_data.strip().split('\n')
    v_c_str = lines[0]
    l = len(v_c_str)
    alphabet = [chr(ord('a') + i) for i in range(l)]
    char_to_type = {c: v_c_str[i] for i, c in enumerate(alphabet)}

    n, m = map(int, lines[1].split())
    rules = []
    line_idx = 2
    for _ in range(m):
        parts = lines[line_idx].split()
        rules.append((int(parts[0]), parts[1], int(parts[2]), parts[3]))
        line_idx += 1
    s = lines[line_idx]

    def check_valid(word):
        for p1, t1, p2, t2 in rules:
            if char_to_type[word[p1-1]] == t1 and char_to_type[word[p2-1]] != t2:
                return False
        return True

    def solve():
        # Build word lexicographically from s
        word = list(s)

        # Strategy: try to find smallest word >= s
        # by deviating at each position

        for dev_pos in range(n):
            # Trial 1: keep prefix s[:dev_pos] and try to fill remainder
            # starting from smallest > s[dev_pos]

            prefix = list(s[:dev_pos])

            # Find smallest char > s[dev_pos]
            idx_s = alphabet.index(s[dev_pos])

            for new_idx in range(idx_s + 1, l):
                prefix.append(alphabet[new_idx])
                fill = [None] * (n - dev_pos - 1)
                success = try_fill(prefix, fill, dev_pos + 1)
                if success:
                    result = prefix + fill
                    if check_valid(result):
                        return ''.join(result)

            # Trial 2: keep s[:dev_pos] and try s[dev_pos] but allow different suffix
            # (Already covered above since we try all >)

        return "-1"

    def try_fill(prefix, fill, pos):
        if pos == n and check_valid(prefix):
            return True
        if pos >= n:
            return False

        # Try to fill with smallest possible
        for char in alphabet:
            prefix[pos] = char
            if check_partial(prefix, pos):
                if pos + 1 == n:
                    return check_valid(prefix)
                fill.append(char)
                if try_fill(prefix, fill, pos + 1):
                    return True
                fill.pop()
            else:
                # Backtrack
                prefix[pos] = ''
        return False

    def check_partial(prefix, pos):
        # Check rules that involve positions 0 to pos-1
        full = [''] + list(prefix)
        for p1, t1, p2, t2 in rules:
            disp1, disp2 = p1 - 1, p2 - 1
            if disp1 < pos and disp2 < pos:
                if char_to_type[full[disp1]] == t1:
                    if char_to_type[full[disp2]] != t2:
                        return False
        return True

    return solve()


