        if line.startswith('1'):
            if current_segment:
                segments.append(current_segment)
                current_segment = []
        else:
            current_segment.append(line.split()[1])
    if current_segment:
        segments.append(current_segment)

    # Collect all unique friends
    friends = set()
    for seg in segments:
        friends.update(seg)

    # Map friends to indices (sorted for consistency)
    friend_list = sorted(friends)
    friend_to_idx = {friend: i for i, friend in enumerate(friend_list)}
    friend_count = len(friend_list)

    # Build conflict matrix: conflict[i][j] = True if friends i and j appear in the same segment
    conflict = [[False] * friend_count for _ in range(friend_count)]
    for seg in segments:
        present = set()
        for friend in seg:
            present.add(friend_to_idx[friend])
        for i in present:
            for j in present:
                if i != j:
                    conflict[i][j] = True

    # Find maximum independent set using bitmask DP
    # Iterate through all 2^(friend_count) masks and find valid ones
    import math

    max_friends = 0

    # For small numbers of friends (up to about 20), brute force is ok
    # For larger, we use a smarter approach
    if friend_count <= 20:
        for mask in range(1 << friend_count):
            # Check if mask is valid (no conflicts among selected friends)
            valid = True
            for i in range(friend_count):
                if (mask >> i) & 1:
                    for j in range(i + 1, friend_count):
                        if (mask >> j) & 1 and conflict[i][j]:
                            valid = False
                            break
                    if not valid:
                        break

            if valid:
                # Count set bits
                count = bin(mask).count('1')
                max_friends = max(max_friends, count)
    else:
        # For larger cases, use recursion with pruning
        memo = {}

        def solve(mask):
            if mask in memo:
                return memo[mask]

            # Find first unselected friend
            first_unselected = -1
            for i in range(friend_count):
                if not (mask & (1 << i)):
                    first_unselected = i
                    break

            if first_unselected == -1:
                return 0

            # Option 1: Don't include first_unselected
            result = solve(mask | (1 << first_unselected))

            # Option 2: Include first_unselected (only if no conflicts with current selection)
            include = True
            for i in range(friend_count):
                if (mask & (1 << i)) and conflict[i][first_unselected]:
                    include = False
                    break

            if include:
                result = max(result, solve(mask | (1 << first_unselected)) + 1)

            memo[mask] = result
            return result

        max_friends = solve(0)

    return str(max_friends)


