def compute_kmp_failure(pattern):
    m = len(pattern)
    if m == 0:
        return []
    failure = [0] * m
    k = 0
    for q in range(1, m):
        while k > 0 and pattern[k] != pattern[q]:
            k = failure[k-1]
        if pattern[k] == pattern[q]:
            k += 1
        failure[q] = k
    return failure

def get_next_k(k, char, virus, failure):
    """Given current virus match length k and new character, return new k"""
    new_k = k
    while new_k > 0 and char != virus[new_k]:
        new_k = failure[new_k - 1]
    if new_k < len(virus) and char == virus[new_k]:
        new_k += 1
    return new_k

