def build_diff_bit(arr, n):
    bit = [0] * (n + 2)
    for i in range(n + 1):
        bit[i+1] += arr[i]
        bit[i+2] -= arr[i]
    return bit

def update_bit(bit, idx, delta, n):
    idx += 1
    while idx <= n + 1:
        bit[idx] += delta
        idx += idx & -idx

def query_bit(bit, idx):
    idx += 1
    s = 0
    while idx > 0:
        s += bit[idx]
        idx -= idx & -idx
    return s

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n = int(lines[0])
    centers = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        if len(parts) >= 2:
            x, y = int(parts[0]), int(parts[1])
            centers.append((float(x), float(y)))

    if n < 3:
        return "-1\n"

    # Compute convex hull using Andrew's algorithm
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    h = sorted(centers, key=lambda p: p[0] * 10**7 + p[1])

    lower = []
    for p in h:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(h):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    if len(lower) == 0 or len(upper) == 0:
        return "-1\n"

    hull = lower[:-1] + upper[:-1]

    if len(hull) < 3:
        return "-1\n"

    # Find the maximum distance between any pair in hull
    max_dist = 0
    for i in range(len(hull)):
        for j in range(i + 1, len(hull)):
            dx = hull[i][0] - hull[j][0]
            dy = hull[i][1] - hull[j][1]
            dist = math.sqrt(dx*dx + dy*dy)
            if dist > max_dist:
                max_dist = dist

    # Answer is max_dist / 2
    result = max_dist / 2.0

    # Format output with enough precision
    return f"{result:.6f}\n"

