def solution(s: str) -> str:
    n = len(s)

    if n == 0:
        return "0"

    # Manacher's algorithm for odd-length palindromes
    t = "^#" + "#".join(s) + "#$"
    m = len(t)
    d = [0] * m
    c, r = 0, 0

    for i in range(1, m - 1):
        mirror = 2 * c - i
        k = d[mirror] if i < r else 0
        if k > r - i:
            k = r - i

        while i - k - 1 >= 0 and i + k + 1 < m and t[i - k - 1] == t[i + k + 1]:
            k += 1
        d[i] = k

        if i + k > r:
            c, r = i, i + k

    best_len = 0
    best_parts = []

    for i in range(1, m, 2):
        center = (i - 1) // 2
        radius = d[i] - 1

        m_start = center - radius
        m_end = center + radius + 1
        m_length = m_end - m_start

        if m_start < 0 or m_length <= 0:
            continue
        if m_length % 2 == 0:
            continue

        left_space = m_start
        right_space = n - m_end

        if left_space <= 0 or right_space <= 0:
            continue

        limit = min(left_space, right_space)

        if limit == 0:
            continue

        for x in range(limit, 0, -1):
            prefix = s[:x]
            suffix = s[n-x:n]
            if prefix == suffix[::-1]:
                total = 2 * x + m_length
                if total > best_len:
                    best_len = total
                    best_parts = [
                        (1, x),
                        (1 + x, m_length),
                        (1 + x + m_length, x)
                    ]
                break

    result = [str(len(best_parts))]
    for start, length in best_parts:
        result.append(f"{start} {length}")

    return "\n".join(result)

