SPF = []

def build_spf(limit):
    """Build smallest prime factor array up to limit."""
    global SPF
    SPF = list(range(limit + 1))
    for i in range(2, int(limit**0.5) + 1):
        if SPF[i] == i:
            for j in range(i * i, limit + 1, i):
                if SPF[j] == j:
                    SPF[j] = i

def factorize(n):
    """Return prime factors of n using SPF."""
    factors = []
    while n > 1:
        if SPF[n] == n:
            factors.append(n)
            break
        else:
            p = SPF[n]
            factors.append(p)
            n //= p
    return factors

def get_divisors(factors):
    """Generate all divisors from prime factor list."""
    divisors = {1}
    p = 2
    while p * p <= factors[-1] if factors else 1:
        if factors.count(p) == len([x for x in factors if x == p]):
            divisors.update(d * p for d in divisors)
            divisors.update(d * q for d in divisors for q in range(2, factors.count(p) + 1))
            n = factors.count(p)
            p += 1
    return divisors

def get_divisors_from_factors(prime_factors):
    """Generate all divisors from prime factorization."""
    divisors = {1}
    for p, count in prime_factors:
        new_divisors = set()
        for d in divisors:
            for i in range(count + 1):
                new_divisors.add(d * (p ** i))
        divisors = new_divisors
    return sorted(divisors)

def calc_cost(a, n, k):
    """Calculate cost to make all boxes divisible by k."""
    cost = 0
    carry = 0
    for val in a:
        r = val % k
        carry += r
        if carry >= k:
            carry -= k
        cost += carry
    return cost if carry == 0 else float('inf')

