def solve_polygon_triangulation(n, poly):
    """Solve polygon triangulation counting problem"""
    MOD = 1000000007

    # Precompute valid diagonals
    valid_diagonal = [[False] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 2, n):
            # Check indices are not adjacent (that would be boundary)
            if (j - 1 == i) or (i == j - 1):
                continue

            # Check if diagonal is valid
            if not seg_intersects_polygon(poly, i, j, n):
                continue

            # Check if it's inside (for concave polygon)
            if not diagonal_is_inside(poly, i, j, n):
                continue

            # Mark as valid
            valid_diagonal[i][j] = True
            valid_diagonal[j][i] = True

    # DP: dp[i][j] = number of ways to triangulate polygon from vertex i to j
    dp = [[0] * n for _ in range(n)]

    def count_memo(i, j, visited):
        if i == j:
            return 1
        if visited[i][j]:
            return dp[i][j]

        count = 0

        # Try all possible intermediate vertices to form triangle (i, k, j)
        for k in range(i + 1, j):
            # Check if triangle (i, k, j) is valid
            diag_valid = valid_diagonal[i][k] and valid_diagonal[k][j]

            if not diag_valid:
                continue

            # Get count from subproblems
            sub1 = count_memo(i, k, visited)
            sub2 = count_memo(k, j, visited)

            if sub1 > 0 and sub2 > 0:
                count = (count + sub1 * sub2) % MOD

        dp[i][j] = count
        visited[i][j] = True
        return count

    return count_memo(0, n - 1, [[False] * n for _ in range(n)])

def seg_intersects_polygon(poly, i, j, n):
    """Check if segment from vertex i to j intersects any other polygon edge"""
    ii, jj = i % n, j % n

    for k in range(n):
        m = (k + 1) % n

        # Skip edges connected to i or j
        if k == ii or m == ii or k == jj or m == jj:
            continue

        # Check if segment (i,j) intersects edge (k,m)
        if segments_intersect_fast(poly[ii], poly[jj], poly[k], poly[m]):
            return False

    return True

def diagonal_is_inside(poly, i, j, n):
    """Check if diagonal truly stays inside the polygon"""
    # For simplicity, use ray casting from midpoint of diagonal

    ii, jj = i % n, j % n
    p1 = poly[ii]
    p2 = poly[jj]

    # Midpoint of diagonal
    mid = ((p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2)

    # Cast ray and count intersections with polygon edges
    intersections = 0
    for k in range(n):
        m = (k + 1) % n
        if k == ii or m == ii or k == jj or m == jj:
            continue

        # Check intersection without touching endpoints
        if segments_intersect_fast(p1, p2, poly[k], poly[m]):
            intersections += 1

    # Odd number of intersections means diagonal is inside
    return intersections % 2 == 1

def solution(input_data):
    """Main solution function"""
    lines = input_data.strip().split('\n')

    n = int(lines[0])
    poly = []

    for i in range(1, n + 1):
        coords = lines[i].split()
        poly.append((int(coords[0]), int(coords[1])))

    # For polygons with n vertices, the number of triangulations is C(n-2) for convex
    # But for general simple polygons, we need to count based on valid diagonals

    MOD = 1000000007

    # Use memoization-based DP
    memo = {}

    def count_triangulations(i, j):
        """Count triangulations of polygon from vertex i to vertex j"""
        key = (min(i, j), max(i, j))
        if key in memo:
            return memo[key]

        if i == j or j == i:
            return 1  # Single vertex, one way (base case)

        if abs(j - i) == 1:
            return 1  # Two adjacent vertices, one way (edge)

        count = 0

        # Try all possible diagonal points k
        for k in range(i + 1, j):
            # Check if both diagonals exist
            i_k = (i + k) % n
            i_k_norm = min(i_k, k - i)
            k_j = (k + j) % n

            if i_k_norm < 0:
                i_k_norm = i_k_norm + n

            diag1_valid = is_valid_diagonal(poly, i, k, n)
            diag2_valid = is_valid_diagonal(poly, k, j, n)

            if diag1_valid and diag2_valid:
                count = (count + count_triangulations(i, k) * count_triangulations(k, j)) % MOD

        memo[key] = count
        return count

    def is_valid_diagonal(poly, i, j, n):
        """Check if diagonal (i,j) goes through polygon interior"""
        ii, jj = i % n, j % n

        # Check if i and j are adjacent
        if (jj == (ii + 1) % n) or (ii == (jj + 1) % n):
            return True  # Boundary edge, valid

        # Check intersection with all other edges
        for k in range(n):
            m = (k + 1) % n

            if k == ii or m == ii or k == jj or m == jj:
                continue

            if k > jj and m > jj and k < ii and m < ii:
                continue  # Skip edges in the other direction

            if segments_intersect_fast(poly[ii], poly[jj], poly[k], poly[m]):
                return False

        return True

    # Handle the polygon as a linear sequence from 0 to n-1
    # Count triangulations by trying different split points
    result = 0
    for k in range(1, n):
        if is_valid_diagonal(poly, 0, k, n):
            result = (result + count_triangulations(0, k)) % MOD

    return str(result % MOD)

