    # Directions based on swap:
    # If swapLR: L->right, R->left
    # If swapUD: U->down, D->up

    # Direction deltas and their button names
    # Normal: U=(−1,0), D=(+1,0), L=(0,−1), R=(0,+1)
    # Swapped differently based on swapLR/swapUD

    directions = {
