        'U': 'D',
        'D': 'U',
        'L': 'R',
        'R': 'L'
    }

    # Map button press to actual direction delta
    button_to_delta = {}
    if swapLR:
        button_to_delta['L'] = (0, 1)   # L acts as R
        button_to_delta['R'] = (0, -1)   # R acts as L
        # U and D remain same if not swapped
    else:
        button_to_delta['L'] = (0, -1)
        button_to_delta['R'] = (0, 1)

    if swapUD:
        button_to_delta['U'] = (1, 0)   # U acts as D
        # D remains same if not swapped
    else:
