        }
    else:
        button_to_delta = {
            'U': (-1, 0),
            'D': (1, 0),
            'L': (0, -1),
            'R': (0, 1)
        }

    # BFS
    from collections import deque

    queue = deque([(start_row, start_col, [])])
    visited = set([(start_row, start_col)])
    path_found = False

    while queue and not path_found:
        r, c, path = queue.popleft()

        if (r, c) == (finish_row, finish_col):
            path_found = True
            result_path = path
            break

        for btn, (dr, dc) in button_to_delta.items():
