        visited[u] = True
        ids[u] = low[u] = id_counter[0]
        id_counter[0] += 1
        stack.append(u)
        on_stack[u] = True

        for v in adj[u]:
            if not visited[v]:
                dfs_tarjan(v)
                low[u] = min(low[u], low[v])
