                low[u] = min(low[u], ids[v])

        if ids[u] == low[u]:
            while stack:
                node = stack.pop()
                on_stack[node] = False
                scc_id[node] = id_counter[0]
                id_counter[0] += 1

    for i in range(1, n + 1):
        if not visited[i]:
