def solution(input_str):
    lines = input_str.strip().split('\n')
    n1, n2, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        u, v = map(int, lines[1 + i].split())
        edges.append((u, v, i + 1))

    # Calculate degrees of each vertex
    deg_l = defaultdict(int)
    deg_r = defaultdict(int)

    for u, v, idx in edges:
        deg_l[u] += 1
        deg_r[v] += 1

    # Find minimum degree across all vertices
    min_degree = 0
    if n1 > 0 and deg_l:
        min_degree = min(deg_l.values())
    if n2 > 0 and deg_r:
        min_degree = min(min_degree, min(deg_r.values()))

    # Output placeholder for k=0 (always 0 edges)
    output = ["0"]

    INF = float('inf')

    def solve_k_covering(k):
        # Build flow network
        source = 0
        sink = n1 + n2 + 1
        nodes = n1 + n2 + 2
        graph = [[] for _ in range(nodes)]

        def add_edge(u, v, cap):
            # Forward edge: [to, capacity, reverse_edge_index, flow]
            reverse_idx = len(graph[v])
            graph[u].append([v, cap, reverse_idx, 0])
            # Backward edge
            forward_idx = len(graph[u]) - 1
            graph[v].append([u, 0, forward_idx, 0])

        # Source to U vertices with capacity k
        for u in range(1, n1 + 1):
            add_edge(source, u, k)

        # V vertices to sink with capacity k
        for v in range(1, n2 + 1):
            v_node = n1 + v
            add_edge(v_node, sink, k)

        # U to V edges (capacity 1 - can select each edge at most once)
        edge_indices = []
        for u, v, edge_idx in edges:
            v_node = n1 + v
            add_edge(u, v_node, 1)
            edge_indices.append((u, v_node, edge_idx))

        # Dinic's algorithm for max flow
        total_flow = 0

        while True:
            # BFS to build level graph
            level = [-1] * nodes
            level[source] = 0
            queue = [source]

            while queue:
                u = queue.pop(0)
                for v, cap, rev, flow in graph[u]:
                    if cap - flow > 0 and level[v] < 0:
                        level[v] = level[u] + 1
                        queue.append(v)

            if level[sink] < 0:
                break

            ptr = [0] * nodes

            def dfs(u, pushed):
                if u == sink or pushed == 0:
                    return pushed
                for i in range(ptr[u], len(graph[u])):
                    ptr[u] = i
                    v, cap, rev, flow = graph[u][i]
                    if level[v] == level[u] + 1 and cap - flow > 0:
                        pushed = dfs(v, min(pushed, cap - flow))
                        graph[u][i][3] -= pushed
                        graph[v][rev][3] += pushed
                        if pushed == 0:
                            break
                    if pushed > 0:
                        break
                return pushed

            while True:
                pushed = dfs(source, INF)
                if pushed == 0:
                    break
                total_flow += pushed

        # Extract edges with flow (U to V edges)
        selected = set()
        for u in range(1, n1 + 1):
            for v_node, cap, rev, flow in graph[u]:
                # Check if this is U -> V edge (v_node >= n1 + 1)
                if v_node >= n1 + 1 and v_node < nodes - 1 and flow > 0:
                    # Find original edge index
                    for edge_u, edge_v_node, edge_idx in edge_indices:
                        if edge_u == u and edge_v_node == v_node:
                            selected.add(edge_idx)
                            break

        # Sort and return
        return sorted(list(selected))

    # For k = 1 to min_degree
    for k in range(1, min_degree + 1):
        selected = solve_k_covering(k)
        output.append(f"{len(selected)} " + " ".join(map(str, selected)))

    return '\n'.join(output)

