    import sys
    sys.setrecursionlimit(200000)

    lines = input_string.strip().split('\n')
    if not lines:
        return ''

    T = int(lines[0])
    results = []

    for i in range(1, T + 1):
        if i >= len(lines):
            break

        parts = lines[i].split()
        if len(parts) < 2:
            results.append('-1')
            continue

        N, K = int(parts[0]), int(parts[1])

        # Edge case: K = 0, identity permutation always works
        if K == 0:
            results.append(' '.join(map(str, range(1, N + 1))))
            continue

        # Edge case: K >= N, impossible since |n - i| < N for all 1 <= n, i <= N
        if K >= N:
            results.append('-1')
            continue

        result = [0] * N
        used = [False] * (N + 1)

        def backtrack(pos):
            if pos == N:
                return True

            # Try numbers in ascending order for lexicographically smallest result
            for n in range(1, N + 1):
                if not used[n] and abs(n - (pos + 1)) >= K:
                    used[n] = True
                    result[pos] = n
                    if backtrack(pos + 1):
                        return True
                    used[n] = False

            return False

        if backtrack(0):
            results.append(' '.join(map(str, result)))
        else:
            results.append('-1')

    return '\n'.join(results)

