        # partitions by working from largest to smallest

        # The problem allows exact sum assignment
        # We use memoization to check feasibility

        memo = {}

        def can_form(counts, m_left, remaining_sum):
            key = (tuple(sorted(counts.items())), m_left, remaining_sum)
            if key in memo:
                return memo[key]

            if m_left == 0:
                return counts is None or (len(counts) == 0 and remaining_sum == 0)

            if sum(counts.values()) == 0:
                return remaining_sum == 0 and m_left == 0

            # Find largest element and try to form a partition
            max_elem = -1
            for e in sorted(counts.keys(), reverse=True):
                if counts[e] > 0:
                    max_elem = e
                    break

            if max_elem == -1:
                return remaining_sum == 0 and m_left == 0

            # Try to use max_elem in forming a valid partition
            # Actually, let's use a different greedy approach

            result = can_form_recursive(counts, m_left, remaining_sum)
            memo[key] = result
            return result

        def can_form_recursive(counts, m_left, remaining_sum):
            if m_left == 0:
                return len(counts) == 0 and remaining_sum == 0

            if remaining_sum == 0:
                return len(counts) == 0 and m_left == 0

            # Greedy: take largest available element
            elems = [e for e, c in counts.items() if c > 0]
            if not elems:
                return False

            for elem in elems:
                c = counts[elem]
                if c == 0:
                    continue

                # Try using this element as the starting point
                new_counts = dict(counts)
                new_counts[elem] -= 1

                if new_counts[elem] == 0:
                    del new_counts[elem]

                # We need to form m_left - 1 more partitions
                # Check if remaining can form valid partitions

                total_needed = remaining_sum - elem
                if total_needed < 0:
                    continue

                # For small m_left, check feasibility
                if m_left - 1 == 0:
                    # Only 1 partition left
                    if elem + total_needed == 0:
                        return True
                    # Need to check if single partition can be formed from remaining
                    single_valid = check_single_partition(new_counts)
                    if single_valid:
                        return True
                    continue

                if can_form_recursive(new_counts, m_left - 1, total_needed):
                    return True

            return False

        def check_single_partition(counts):
            # Count total elements
            total_elements = sum(counts.values())
            if total_elements == 0:
                return True

            # Find the prairie partition that matches these elements
            # Try all possible partitions
            for k in range(total_elements // 2 + 2):
                base_sum = (1 << k) - 1
                if base_sum > 1:
                    for r in range(base_sum - 1, (1 << k) + 1):
                        part = base_sum + r
                        if counts.get(part, 0) >= 1:
                            return True

            return False

        result = can_form(dict(cnt), m, total)
        return result

    valid_ms = []
    for m in range(1, n + 1):
